function escSql(v) {
  if (v === undefined || v === null) return "NULL";
  if (typeof v === "number") return Number.isFinite(v) ? String(v) : "NULL";
  const s = String(v).replace(/\\/g, "\\\\").replace(/'/g, "''");
  return `'${s}'`;
}

function toNumberTR(s) {
  if (s === undefined || s === null) return null;
  s = String(s).trim();
  if (!s || s === "-") return null;

  // % işareti kaldır
  s = s.replace("%", "").trim();

  // 656.812.433,53 -> 656812433.53
  s = s.replace(/\./g, "").replace(",", ".");
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function todayISO() {
  // UTC date (YYYY-MM-DD). İstersen TR timezone'a göre de yaparız.
  return new Date().toISOString().slice(0, 10);
}

// ---------- PARSE (senin metin formatına göre) ----------
function parseTefasLikeText(raw) {
  if (Array.isArray(raw)) raw = raw.join("\n");
  raw = String(raw ?? "");

  const lines = raw
    .replace(/\r/g, "")
    .split("\n")
    .map(s => s.trim())
    .filter(Boolean)
    .filter(s =>
      !s.startsWith("Bilgi [") &&
      !s.startsWith("Grafik [") &&
      s !== "Grafik yükleniyor..." &&
      s !== "Karşılaştırma bölümü yükleniyor..."
    );

  const result = {
    kv: {},                // key-value alanlar (Fon Kodu, ISIN, vs)
    assetAllocation: [],   // [{type, ratio}]
    returns: []            // [{period, value}]
  };

  const singleValueKeys = new Set([
    "Fon Kodu","ISIN Kodu","Platform Durumu","İşlem Başlama Saati","Son İşlem Saati",
    "Fon Alış Valörü","Fon Satış Valörü","Giriş Komisyonu","Çıkış Komisyonu",
    "Fonun Faiz İçeriği","Fon Risk Değeri",
    "Son Fiyat (TL)","Günlük Getiri (%)","Pay (Adet)","Fon Toplam Değer (TL)",
    "Kategorisi","Son 1 Yıllık Kategori Derecesi","Yatırımcı Sayısı","Pazar Payı"
  ]);

  let section = "kv"; // kv | asset | returns

  for (let i = 0; i < lines.length; i++) {
    const s = lines[i];

    if (s === "FON VARLIK DAĞILIMI") { section = "asset"; continue; }
    if (s === "GETIRI BILGISI") { section = "returns"; continue; }
    if (s === "FON BILGISI") { section = "kv"; continue; }

    if (section === "asset" && (s === "Varlık Türü" || s === "Oran (%)")) continue;

    // returns: "Son X Getirisi" + sonraki satır değer
    if (section === "returns" && s.startsWith("Son ") && s.includes("Getirisi")) {
      const valueLine = lines[i + 1] ?? null;
      result.returns.push({ period: s, value: toNumberTR(valueLine) });
      i += 1;
      continue;
    }

    // asset: type + % oran
    if (section === "asset") {
      const next = lines[i + 1] ?? null;
      if (next && /%$/.test(next)) {
        result.assetAllocation.push({ type: s, ratio: toNumberTR(next) });
        i += 1;
        continue;
      }
    }

    // key-value
    if (singleValueKeys.has(s)) {
      const v = lines[i + 1] ?? null;
      result.kv[s] = v === "-" ? null : v;
      i += 1;
      continue;
    }
  }

  return result;
}

// ---------- KV -> DB alan map ----------
function buildDbRow(parsed) {
  const kv = parsed.kv || {};

  // returns map
  const ret = {};
  for (const r of (parsed.returns || [])) ret[r.period] = r.value;

  // asset'leri iki text alanına JSON olarak basacağız
  const assetList = (parsed.assetAllocation || []).map(x => x.type);
  const assetVals = (parsed.assetAllocation || []).map(x => x.ratio);

  return {
    code: kv["Fon Kodu"] ?? null,
    isin_code: kv["ISIN Kodu"] ?? null,
    platform_status: kv["Platform Durumu"] ?? null,
    interest_content: kv["Fonun Faiz İçeriği"] ?? null,
    risk_value: toNumberTR(kv["Fon Risk Değeri"]),

    last_price: toNumberTR(kv["Son Fiyat (TL)"]),
    daily_return: toNumberTR(kv["Günlük Getiri (%)"]),
    shares_outstanding: toNumberTR(kv["Pay (Adet)"]),
    total_value: toNumberTR(kv["Fon Toplam Değer (TL)"]),

    category: kv["Kategorisi"] ?? null,
    category_rank: kv["Son 1 Yıllık Kategori Derecesi"] ?? null,

    investor_count: (() => {
      const n = toNumberTR(kv["Yatırımcı Sayısı"]);
      return n == null ? null : Math.trunc(n);
    })(),

    market_share: toNumberTR(kv["Pazar Payı"]),

    return_1m: ret["Son 1 Ay Getirisi"] ?? null,
    return_3m: ret["Son 3 Ay Getirisi"] ?? null,
    return_6m: ret["Son 6 Ay Getirisi"] ?? null,
    return_1y: ret["Son 1 Yıl Getirisi"] ?? null,

    fon_varlik_dagilim_list: JSON.stringify(assetList),
    fon_varlik_dagilim_degerler: JSON.stringify(assetVals),

    created_at: todayISO()
  };
}

// ---------- Query üretimi (NAME'e dokunma!) ----------
function makeQueries(row) {
  if (!row.code) {
    throw new Error("Fon Kodu (code) bulunamadı. Metinde 'Fon Kodu' yok.");
  }

  // 1) tefas_funds 
  const qFunds = `
INSERT INTO tefas_funds
  (code, isin_code, platform_status, interest_content, risk_value, fon_varlık_dagılım_list, fon_varlık_dagılım_degerler)
VALUES
  (${escSql(row.code)}, ${escSql(row.isin_code)}, ${escSql(row.platform_status)}, ${escSql(row.interest_content)}, ${row.risk_value ?? "NULL"}, ${escSql(row.fon_varlik_dagilim_list)}, ${escSql(row.fon_varlik_dagilim_degerler)})
ON DUPLICATE KEY UPDATE
  isin_code = VALUES(isin_code),
  platform_status = VALUES(platform_status),
  interest_content = VALUES(interest_content),
  risk_value = VALUES(risk_value),
  fon_varlık_dagılım_list = VALUES(fon_varlık_dagılım_list),
  fon_varlık_dagılım_degerler = VALUES(fon_varlık_dagılım_degerler),
  updated_at = CURRENT_TIMESTAMP;
`.trim();

  // 2) fund_stats_history UPSERT
  const qHistory = `
INSERT INTO fund_stats_history
  (code, created_at, last_price, daily_return, shares_outstanding, total_value, category, category_rank, investor_count, market_share, return_1m, return_3m, return_6m, return_1y)
VALUES
  (${escSql(row.code)}, ${escSql(row.created_at)}, ${row.last_price ?? "NULL"}, ${row.daily_return ?? "NULL"}, ${row.shares_outstanding ?? "NULL"}, ${row.total_value ?? "NULL"}, ${escSql(row.category)}, ${escSql(row.category_rank)}, ${row.investor_count ?? "NULL"}, ${row.market_share ?? "NULL"}, ${row.return_1m ?? "NULL"}, ${row.return_3m ?? "NULL"}, ${row.return_6m ?? "NULL"}, ${row.return_1y ?? "NULL"})
ON DUPLICATE KEY UPDATE
  last_price = VALUES(last_price),
  daily_return = VALUES(daily_return),
  shares_outstanding = VALUES(shares_outstanding),
  total_value = VALUES(total_value),
  category = VALUES(category),
  category_rank = VALUES(category_rank),
  investor_count = VALUES(investor_count),
  market_share = VALUES(market_share),
  return_1m = VALUES(return_1m),
  return_3m = VALUES(return_3m),
  return_6m = VALUES(return_6m),
  return_1y = VALUES(return_1y);
`.trim();

  return [qFunds, qHistory];
}

// ---------- n8n ENTRY ----------
const inputJson = $input.first().json;

// genelde HTML node'dan "basliklar" array geliyor
const basliklar = inputJson.basliklar ?? inputJson.raw ?? inputJson.text ?? "";
const rawText = Array.isArray(basliklar) ? basliklar[0] : basliklar;

const parsed = parseTefasLikeText(rawText);
const row = buildDbRow(parsed);
const [q1, q2] = makeQueries(row);

return [
  { json: { query: q1, code: row.code, created_at: row.created_at } },
  { json: { query: q2, code: row.code, created_at: row.created_at } }
];
